using System;
using System.Collections;
using System.Collections.Generic;
using Astrea.BattleActions;
using Astrea.RunModifiers;
using FMOD.Studio;
using FMODUnity;
using LittleLeo;
using LittleLeo.Events;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "OmniSoulEffect", menuName = "Data/Battle/Effects/Enemy/OmniSoul Effect")]
public class OmniSoulEffect : Effect
{
	[Header("Omni Soul Effect")]
	[SerializeField]
	private CurrentCorruptedAnimals currentCorruptedAnimals;

	[SerializeField]
	private CorruptedAnimalData astreaBallCorruptedAnimalData;

	[SerializeField]
	private SolarRebirthAction solarRebirthAction;

	[SerializeField]
	private BattleCorruptedAnimals astreaSecondPhasePackage;

	[SerializeField]
	private VoidEvent OnRecoverAllHearts;

	[SerializeField]
	private VoidEvent OnStopBattleBGM;

	[Header("Second Phase Animation")]
	[SerializeField]
	private float delayToBouncingAnimation;

	[SerializeField]
	private float delayToEndOfBattleInitialize;

	[Header("Astrea Level")]
	[SerializeField]
	private DifficultyLevel astreaLevel;

	[Header("VFX")]
	[SerializeField]
	private float dealayToFeedbackAndMainVFX = 0.7f;

	[SerializeField]
	private float delayToEffectSpread = 1f;

	[Header("SFX")]
	[SerializeField]
	private EventReference wobblingSFX;

	[Header("Achievements")]
	[SerializeField]
	private StellarHasteAchievementData stelllarHasteAchievementData;

	[NonSerialized]
	private List<GameObject> astreasChangingState = new List<GameObject>();

	[NonSerialized]
	private bool moreThanOnceAstreaDefeatedFirstAstreaAlreadyCalledGoToSecondPhase;

	public List<GameObject> corruptedAnimalObjects = new List<GameObject>();

	public EventInstance LoopableEventInstance;

	public CorruptedAnimalData AstreaBallCorruptedAnimalData => astreaBallCorruptedAnimalData;

	public void SetAstreaBallCorruptedAnimalData(CorruptedAnimalData astreaBallCorruptedAnimalData)
	{
		this.astreaBallCorruptedAnimalData = astreaBallCorruptedAnimalData;
	}

	public void SetAstreaSecondPhasePackage(BattleCorruptedAnimals astreaSecondPhasePackage)
	{
		this.astreaSecondPhasePackage = astreaSecondPhasePackage;
	}

	public override void Initialize(int effectAmount, GameObject effectOwner, GameObject source)
	{
		corruptedAnimalObjects = currentCorruptedAnimals.activeCorruptedAnimals.Duplicate();
		astreasChangingState.Clear();
		moreThanOnceAstreaDefeatedFirstAstreaAlreadyCalledGoToSecondPhase = false;
	}

	public void ShareEffectWithOtherAstreas(GameObject effectToShareSource, Effect effectToShare, int effectAmount, GameObject oneEffectOwner)
	{
		if (!(effectToShareSource != oneEffectOwner))
		{
			List<GameObject> enemiesNotInfinityCorruptionAndNotEffectOwner = currentCorruptedAnimals.GetEnemiesNotInfinityCorruptionAndNotEffectOwner(oneEffectOwner);
			if (enemiesNotInfinityCorruptionAndNotEffectOwner.Count > 0)
			{
				ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueAction(ShareEffectWithOtherAstreasCoroutine(oneEffectOwner, enemiesNotInfinityCorruptionAndNotEffectOwner, effectToShare, effectAmount));
			}
		}
	}

	private IEnumerator ShareEffectWithOtherAstreasCoroutine(GameObject oneEffectOwner, List<GameObject> enemiesToApplyEffect, Effect effectToShare, int effectAmount)
	{
		yield return new WaitForSeconds(IsVFXEnabled() ? dealayToFeedbackAndMainVFX : 0.5f);
		PlayEffectActivationSFX();
		oneEffectOwner.GetComponent<UnitEffects>().IsEffectActive(this);
		SpawnVFX(GetVFXOwnerPosition(oneEffectOwner), 3f);
		for (int i = 0; i < enemiesToApplyEffect.Count; i++)
		{
			SpawnSecondVFX(GetVFXOwnerPosition(enemiesToApplyEffect[i]), 3f);
		}
		yield return new WaitForSeconds(IsVFXEnabled() ? delayToEffectSpread : 0.5f);
		for (int j = 0; j < enemiesToApplyEffect.Count; j++)
		{
			enemiesToApplyEffect[j].GetComponent<UnitEffects>().AddEffect(effectToShare, effectAmount);
		}
	}

	public void OneAstreaDefeatedTurnIntoBall(GameObject effectOwner, List<EffectInstance> activeEffectsListBeforeRemoval)
	{
		Debug.Log("-------OneAstreaDefeatedTurnIntoBall-------");
		if (!astreasChangingState.Contains(effectOwner))
		{
			astreasChangingState.Add(effectOwner);
			ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueAstreaBallAction(OneAstreaDefeatedTurnIntoBallCoroutine(effectOwner, activeEffectsListBeforeRemoval));
			ReferenceSingleton<GameStateManager>.Instance.SetActionsQueueState();
		}
	}

	private IEnumerator OneAstreaDefeatedTurnIntoBallCoroutine(GameObject effectOwner, List<EffectInstance> activeEffectsListBeforeRemoval)
	{
		Debug.Log("----- OneAstreaDefeatedTurnIntoBallCoroutine -----");
		if (currentCorruptedAnimals.IsAnyEnemyActive())
		{
			Debug.Log("----- currentCorruptedAnimals.IsAnyEnemyActive() -----");
			solarRebirthAction.PopulateAstreaReturnPreviewEffects(effectOwner, activeEffectsListBeforeRemoval);
			CorruptedAnimalEffects corruptedAnimalEffects = effectOwner.GetComponent<CorruptedAnimalEffects>();
			corruptedAnimalEffects.RemoveAllEffectsWithCallbacks();
			float extraFillDuration = 0.5f;
			corruptedAnimalEffects.ToggleHideCorruption(value: false);
			CorruptedAnimalCorruptionStats component = effectOwner.GetComponent<CorruptedAnimalCorruptionStats>();
			component.SetInfinityCorruption(value: true);
			component.ModifyMaxCorruption(999f, 999f, extraFillDuration, changingToInfinityCorruption: true);
			int difficultyLevelModifyEnemiesHighestIndex = astreaLevel.GetDifficultyLevelModifyEnemiesHighestIndex();
			int maxOverCorruption = astreaBallCorruptedAnimalData.GetMaxOverCorruption(difficultyLevelModifyEnemiesHighestIndex);
			maxOverCorruption += ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.GetCrypticMementoOmenActionAmount();
			corruptedAnimalEffects.ToggleHideOverCorruption(value: false);
			component.ModifyMaxOverCorruptionAnimatedFill(0f, maxOverCorruption, extraFillDuration);
			if (component.OverCorrupted)
			{
				component.CorruptedAnimalOverCorruption.IgnoreNextOverCorruption();
			}
			CorruptedAnimalInitializer component2 = effectOwner.GetComponent<CorruptedAnimalInitializer>();
			component2.CorruptedAnimalOverCorruption.Initialize(astreaBallCorruptedAnimalData);
			component2.InitializeTooltipNameInstance(astreaBallCorruptedAnimalData);
			effectOwner.GetComponent<CorruptedAnimalSpriteControl>().SetCorruptedAnimalData(astreaBallCorruptedAnimalData);
			effectOwner.GetComponent<UnitsDiceActivation>().StoreDice();
			yield return new WaitForSeconds(0.2f);
			corruptedAnimalEffects.Initialize(astreaBallCorruptedAnimalData, startBattleInitialize: false);
			yield return new WaitForSeconds(0.2f);
			astreasChangingState.Remove(effectOwner);
		}
		else
		{
			Debug.Log("----- currentCorruptedAnimals NO ENEMY ACTIVE-----");
			effectOwner.GetComponent<UnitsDiceActivation>().StoreDice();
			bool num = astreasChangingState.Count > 1;
			bool flag = false;
			if (!num)
			{
				flag = true;
			}
			else if (!moreThanOnceAstreaDefeatedFirstAstreaAlreadyCalledGoToSecondPhase)
			{
				flag = true;
				moreThanOnceAstreaDefeatedFirstAstreaAlreadyCalledGoToSecondPhase = true;
			}
			if (flag)
			{
				ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueAfterAction(GoToSecondPhaseCoroutine());
			}
		}
	}

	private IEnumerator GoToSecondPhaseCoroutine()
	{
		ReferenceSingleton<GameStateManager>.Instance.EndPlayerTurnState.AstreaFirstPhaseDefeated();
		stelllarHasteAchievementData.Unlock();
		yield return new WaitForSeconds(delayToBouncingAnimation);
		OnStopBattleBGM.Raise();
		for (int i = 0; i < corruptedAnimalObjects.Count; i++)
		{
			CorruptedAnimalSpriteControl component = corruptedAnimalObjects[i].GetComponent<CorruptedAnimalSpriteControl>();
			component.SetCorruptedAnimalData(AstreaBallCorruptedAnimalData);
			component.PlayAnimationForcedCoroutine(ReferenceSingleton<CoroutineHandler>.Instance, AnimationType.Attack, AnimationChangeType.StayInTheNewAnimationLooping);
		}
		ReferenceSingleton<SFXHandler>.Instance.PlayLoopableSFX(ref LoopableEventInstance, wobblingSFX);
		yield return new WaitForSeconds(delayToEndOfBattleInitialize);
		ReferenceSingleton<BattleHandler>.Instance.EndOfBattleInitialize();
		RestlessJourneyRunModifier restlessJourneyRunModifier = ReferenceSingleton<RunModifiersManager>.Instance.RestlessJourneyRunModifier;
		if (!astreaLevel.IsDontRecoverHeartsDifficultyLevelActive() && restlessJourneyRunModifier == null)
		{
			OnRecoverAllHearts.Raise();
		}
		SetForcedCurrentBattleCorruptedAnimalsToAstreaSecondPhase();
		yield return InvokeAlternatives.WaitForFrames(3);
	}

	public void SetForcedCurrentBattleCorruptedAnimalsToAstreaSecondPhase()
	{
		ReferenceSingleton<BattleHandler>.Instance.SetForcedCurrentBattleCorruptedAnimals(astreaSecondPhasePackage);
	}
}
